PARAMS = {"length": {"value": 140.0, "unit": "mm", "provenance": "measured", "evidence": "TOP VIEW and FRONT VIEW overall dimension 140.0"}, "width": {"value": 40.0, "unit": "mm", "provenance": "measured", "evidence": "TOP VIEW and RIGHT VIEW overall dimension 40.0"}, "height": {"value": 70.0, "unit": "mm", "provenance": "measured", "evidence": "RIGHT VIEW dimension 70.0, FRONT VIEW 69.9 nominal"}, "base_thickness": {"value": 12.0, "unit": "mm", "provenance": "inferred", "evidence": "FRONT/RIGHT bottom band proportion, no step dimension on drawing"}, "bolt_hole_diameter": {"value": 14.0, "unit": "mm", "provenance": "inferred", "evidence": "TOP circles and FRONT/RIGHT dashed lines, scaled to views"}, "bolt_hole_end_offset": {"value": 28.0, "unit": "mm", "provenance": "inferred", "evidence": "TOP circle centres scaled from each end of 140 mm flange"}, "pedestal_width": {"value": 88.0, "unit": "mm", "provenance": "inferred", "evidence": "FRONT stepped outline scaled against 140 mm overall length"}, "pedestal_top_height": {"value": 28.0, "unit": "mm", "provenance": "inferred", "evidence": "FRONT wide pedestal step scaled against 70 mm height"}, "housing_width": {"value": 64.0, "unit": "mm", "provenance": "inferred", "evidence": "FRONT arch width scaled against 140 mm length, equals twice cap radius"}, "housing_depth": {"value": 28.0, "unit": "mm", "provenance": "inferred", "evidence": "TOP/RIGHT single housing face line, rear-flush housing within 40 mm width"}, "lower_flange_width": {"value": 76.0, "unit": "mm", "provenance": "inferred", "evidence": "TOP paired vertical lines either side of housing and FRONT shoulder step"}, "lower_flange_top_height": {"value": 32.0, "unit": "mm", "provenance": "inferred", "evidence": "FRONT shoulder step between pedestal top and bore split, scaled"}, "bore_diameter": {"value": 36.0, "unit": "mm", "provenance": "inferred", "evidence": "FRONT bore circle scaled against arch and overall height"}, "bore_centre_height": {"value": 38.0, "unit": "mm", "provenance": "inferred", "evidence": "FRONT bore centre and cap split line scaled against 70 mm height"}, "cap_outer_radius": {"value": 32.0, "unit": "mm", "provenance": "inferred", "evidence": "FRONT semicircular arch: bore centre 38 plus radius 32 reaches 70 mm top"}}
length = P("length")
width = P("width")
height = P("height")
baseThickness = P("base_thickness")
boltHoleDiameter = P("bolt_hole_diameter")
boltHoleEndOffset = P("bolt_hole_end_offset")
pedestalWidth = P("pedestal_width")
pedestalTop = P("pedestal_top_height")
housingWidth = P("housing_width")
housingDepth = P("housing_depth")
lowerFlangeWidth = P("lower_flange_width")
lowerFlangeTop = P("lower_flange_top_height")
boreDiameter = P("bore_diameter")
boreCentre = P("bore_centre_height")
capRadius = P("cap_outer_radius")
centreX = length / 2.0
rearY = -width / 2.0
grey = "#888c90"
baseSolid = cq.Solid.makeBox(length, width, baseThickness, cq.Vector(0, rearY, 0))
for holeX in (boltHoleEndOffset, length - boltHoleEndOffset):
    holeTool = cq.Solid.makeCylinder(boltHoleDiameter / 2.0, baseThickness + 4.0, cq.Vector(holeX, 0, -2.0), cq.Vector(0, 0, 1))
    baseSolid = baseSolid.cut(holeTool)
pedestalSolid = cq.Solid.makeBox(pedestalWidth, width, pedestalTop - baseThickness, cq.Vector(centreX - pedestalWidth / 2.0, rearY, baseThickness))
flangeSolid = cq.Solid.makeBox(lowerFlangeWidth, housingDepth, lowerFlangeTop - pedestalTop, cq.Vector(centreX - lowerFlangeWidth / 2.0, rearY, pedestalTop))
mainLowerSolid = cq.Solid.makeBox(housingWidth, housingDepth, boreCentre - lowerFlangeTop, cq.Vector(centreX - housingWidth / 2.0, rearY, lowerFlangeTop))
lowerSolid = flangeSolid.fuse(mainLowerSolid)
boreTool = cq.Solid.makeCylinder(boreDiameter / 2.0, housingDepth + 6.0, cq.Vector(centreX, rearY - 3.0, boreCentre), cq.Vector(0, 1, 0))
lowerSolid = lowerSolid.cut(boreTool)
capCylinder = cq.Solid.makeCylinder(capRadius, housingDepth, cq.Vector(centreX, rearY, boreCentre), cq.Vector(0, 1, 0))
capBox = cq.Solid.makeBox(housingWidth, housingDepth, height - boreCentre, cq.Vector(centreX - housingWidth / 2.0, rearY, boreCentre))
capSolid = capCylinder.intersect(capBox)
capSolid = capSolid.cut(boreTool)
parts = [{"name": "base_flange", "shape": baseSolid, "colour": grey, "material": "metal"}, {"name": "pedestal_block", "shape": pedestalSolid, "colour": grey, "material": "metal"}, {"name": "lower_bearing_housing", "shape": lowerSolid, "colour": grey, "material": "metal"}, {"name": "bearing_cap", "shape": capSolid, "colour": grey, "material": "metal"}]